const issued=new WeakMap(),read=l.read,sha=l.sha;
function fresh(ctx){l.assertContext(ctx);assert.equal(ctx.location,'fresh');return ctx;}
function bound(ctx,binding){fresh(ctx);epoch.boundEpoch(binding);assert.equal(binding.containerId,ctx.containerId);const snapshot=structuredClone(binding);epoch.boundEpoch(snapshot);assert.equal(snapshot.containerId,ctx.containerId);for(const d of snapshot.dependencies)assert.equal(sha(read(d.path)),d.sha256);return l.deepFreeze(snapshot);}
function ordered(...times){const values=times.map(t=>{const n=Date.parse(t);assert(Number.isFinite(n));return n;});for(let i=1;i<values.length;i++)assert(values[i-1]<=values[i],'Raw receipt temporal order violated');}
function refs(dir){assert.equal(typeof dir,'string');return ['process.json','stdout','stderr'].map(name=>{const path=dir+'/'+name,bytes=read(path);return{path,bytes:bytes.length,sha256:sha(bytes)};});}
function sameRefs(rows){for(const row of rows){const bytes=read(row.path);assert.equal(bytes.length,row.bytes);assert.equal(sha(bytes),row.sha256);}}
function sample(dir,args){const before=refs(dir),r=l.b.commandEvidence(dir,args);sameRefs(before);epoch.processSuccess(r);return{run:r,refs:before};}
function token(kind,ctx,binding,data,view){
 const result=l.deepFreeze({status:view.status,kind,contextId:ctx.contextId,epochDigest:sha(JSON.stringify(binding)),commandAdmission:false,proofAcceptance:false,artifactAcceptance:false,semanticAcceptance:false,sourceCensusVerified:false,...view}),record=l.deepFreeze({kind,ctx,binding,...data});
 // All composed-reader awaits are behind us. Do not yield between final custody and issuance.
 try{bound(ctx,binding);sameRefs(record.refs);}catch(cause){const error=new AggregateError([cause],'Final receipt custody changed before token issuance');error.phases=['final-custody'];throw error;}
 issued.set(result,record);return result;
}
function get(t,kind){assert(issued.has(t),'Token was not issued by this adapter');assert(Object.isFrozen(t));const data=issued.get(t);assert.equal(data.kind,kind);return data;}
// Sequential independent attempts keep falsey errors and never invent another process failure
// when an ordering operand is absent. The fourth phase only runs comparisons when all exist.
async function independent(names,actions,finish){const values=[],errors=[],phases=[];await l.cleanupAttempt(async()=>{try{values[0]=await actions[0]();}catch(e){errors.push(e);phases.push(names[0]);}},async()=>{try{values[1]=await actions[1]();}catch(e){errors.push(e);phases.push(names[1]);}},async()=>{if(actions[2])try{values[2]=await actions[2]();}catch(e){errors.push(e);phases.push(names[2]);}},async()=>{if(errors.length===0)try{await finish(values);}catch(e){errors.push(e);phases.push('ordering');}});if(errors.length){const error=new AggregateError(errors,'Independent temporal receipt validation failed');error.phases=phases;throw error;}return values;}

export function epochRecord(ctx,binding,dir){const b=bound(ctx,binding),inspect=sample(dir+'/inspect',['inspect','--format',epochFormat,ctx.containerId]),boot=sample(dir+'/boot',['exec',ctx.containerId,'cat','/proc/sys/kernel/random/boot_id']);epoch.epochIdentity(JSON.parse(inspect.run.stdout),boot.run.stdout.toString(),b);ordered(b.startedAt,inspect.run.p.started,inspect.run.p.ended,boot.run.p.started,boot.run.p.ended);return token('epoch',ctx,b,{refs:[...inspect.refs,...boot.refs]},{status:'PASS_EPOCH_RECEIPTS_ONLY',started:inspect.run.p.started,ended:boot.run.p.ended});}
export function memoryRecord(ctx,binding,dir){const b=bound(ctx,binding),r=sample(dir,['exec',ctx.containerId,'cat','/sys/fs/cgroup/memory.events']),memory={};const text=r.run.stdout.toString().trim();for(const line of text.split('\n')){const[k,v]=line.split(/\s+/);assert(/^\d+$/.test(v));assert(!Object.hasOwn(memory,k));memory[k]=v;}for(const k of ['oom','oom_kill'])assert(Object.hasOwn(memory,k));old.sameMemory(b.memory,memory);return token('memory',ctx,b,{refs:r.refs},{status:'PASS_MEMORY_RECEIPTS_ONLY',started:r.run.p.started,ended:r.run.p.ended,memory});}
export async function epochMemoryRecord(ctx,binding,dir){const rows=await independent(['epoch','memory'],[()=>epochRecord(ctx,binding,dir+'/epoch'),()=>memoryRecord(ctx,binding,dir+'/memory')],([e,m])=>ordered(e.ended,m.started,m.ended));const[e,m]=rows,ed=get(e,'epoch'),md=get(m,'memory');assert.equal(e.epochDigest,m.epochDigest);return token('boundary',ctx,ed.binding,{refs:[...ed.refs,...md.refs]},{status:'PASS_EPOCH_MEMORY_RECEIPTS_ONLY',started:e.started,ended:m.ended});}
export async function preCommand(ctx,binding,verb,root,dir){fresh(ctx);assert(['check','verify'].includes(verb));assert.equal(root,l.rootFor(ctx,root.module));const boundary=await epochMemoryRecord(ctx,binding,dir),data=get(boundary,'boundary');const e=epochRecord(ctx,data.binding,dir+'/epoch'),m=memoryRecord(ctx,data.binding,dir+'/memory');sameRefs(data.refs);return token('pre',ctx,data.binding,{refs:data.refs,verb,root,epoch:e,memory:m,argv:l.commandArgs(ctx,verb,root.path)},{status:'PASS_PRE_TEMPORAL_RECEIPTS_ONLY_NOT_COMMAND_ADMISSION',verb,module:root.module,started:e.started,ended:m.ended});}
export async function postCommand(preToken,commandDir,postDir){const pre=get(preToken,'pre');fresh(pre.ctx);
 const [command,memory,after]=await independent(['command','post-memory','post-epoch'],[
  ()=>{bound(pre.ctx,pre.binding);sameRefs(pre.refs);const before=refs(commandDir),raw=custody.phaseRunRecord(pre.ctx,pre.verb,pre.root,commandDir);sameRefs(before);assert([0,1].includes(raw.p.status),'Command status must be zero or one');const j=JSON.parse(raw.stdout);assert.equal(j.spec,'lexlean/command-result/1');assert.equal(j.command,pre.verb);assert.equal(j.exit_code,raw.p.status);assert.equal(j.success,raw.p.status===0);for(const k of ['modules','artifacts','diagnostics'])assert(Array.isArray(j[k]));if(raw.p.status===0){assert.deepEqual(j.diagnostics,[]);assert.deepEqual(j.modules,pre.root.closure);}return{dir:commandDir,process:structuredClone(raw.p),stdout:raw.stdout.toString(),stderr:raw.stderr.toString(),refs:before};},
  ()=>memoryRecord(pre.ctx,pre.binding,postDir+'/memory'),
  ()=>epochRecord(pre.ctx,pre.binding,postDir+'/epoch')
 ],([c,m,e])=>{assert.equal(m.epochDigest,preToken.epochDigest);assert.equal(e.epochDigest,preToken.epochDigest);old.sameMemory(pre.memory.memory,m.memory);ordered(pre.epoch.ended,pre.memory.started,pre.memory.ended,c.process.started,c.process.ended,m.started,m.ended,e.started);sameRefs(pre.refs);sameRefs(c.refs);sameRefs(get(m,'memory').refs);sameRefs(get(e,'epoch').refs);});
 return token('post',pre.ctx,pre.binding,{refs:[...pre.refs,...command.refs,...get(memory,'memory').refs,...get(after,'epoch').refs]},{status:'PASS_COMMAND_TEMPORAL_RECEIPTS_ONLY_NOT_PROOF_ACCEPTANCE',verb:pre.verb,module:pre.root.module,command,started:preToken.started,ended:after.ended});
}
export function executionPrerequisite(){l.prerequisite(null);throw Error('Actual full78 restoration and fresh epoch are not bound; no executor exists');}

